% a) Create t and C
t = [0 1 2 3 4];
C = [10 6 4 3 2];

% b) Estimate AUC using trapz
AUC = trapz(t, C);
fprintf('AUC: %.1f mg*h/L\n', AUC);

% c) Confirm by hand with the composite trapezoidal formula
h = t(2) - t(1);
AUC_manual = h * ((C(1) + C(end))/2 + sum(C(2:end-1)));
disp(isequal(AUC, AUC_manual))

% a) Manual linear interpolation
x = [0.4 0.9];
y = [98 90];
slope = (y(2) - y(1)) / (x(2) - x(1));
spo2_manual = y(1) + slope * (0.65 - x(1));

% b) Check with interp1
spo2_interp1 = interp1(x, y, 0.65);

% c) Display and compare
disp(spo2_manual)
disp(spo2_interp1)
valuesMatch = abs(spo2_manual - spo2_interp1) < 1e-9;
disp(valuesMatch)

% a) Create the calibration data
dialSetting = [1 2 3 4 5];
flowRate_mLhr = [48 101 149 205 249];

% b) Estimate flow rate at a single dial setting
flow_at_2_5 = interp1(dialSetting, flowRate_mLhr, 2.5);
disp(flow_at_2_5)

% c) Estimate flow rates at two dial settings at once
flow_multi = interp1(dialSetting, flowRate_mLhr, [1.5 3.5]);
disp(flow_multi)

% a) Create t and flow
t = [0 1 2 3 4];
flow = [30 45 40 35 25];

% b) Estimate total output
totalOutput = trapz(t, flow);
fprintf('Total output: %.1f mL\n', totalOutput);

% c) Number of trapezoids used
numTrapezoids = length(t) - 1;
disp(numTrapezoids)

% a) Define f and the exact value
f = @(x) x.^2;
trueValue = 64/3; % by hand: integral of x^2 from 0 to 4 is [x^3/3] = 64/3

% b) Trapezoidal estimate, h = 1
x = 0:1:4;
trapEst = trapz(x, f(x));

% c) Midpoint estimate using the four interval midpoints
midpoints = [0.5 1.5 2.5 3.5];
h = 1;
midEst = h * sum(f(midpoints));

% d) Absolute errors
errTrap = abs(trapEst - trueValue);
errMid = abs(midEst - trueValue);
fprintf('Trapezoidal error: %.4f\n', errTrap);
fprintf('Midpoint error: %.4f\n', errMid);
% The midpoint rule is noticeably more accurate here (about half the error).

% a) h = 1
f = @(x) x.^2;
trueValue = 64/3;
x1 = 0:1:4;
est1 = trapz(x1, f(x1));
err1 = abs(est1 - trueValue);

% b) h = 0.5
x2 = 0:0.5:4;
est2 = trapz(x2, f(x2));
err2 = abs(est2 - trueValue);

% c) Ratio of errors
ratio = err1 / err2;
fprintf('Error ratio: %.4f\n', ratio);

% d) The ratio is approximately 4: halving h roughly quarters the error,
% consistent with the trapezoidal rule's error scaling as O(h^2).

% a) Create the data
time = [0 4 8];
HR = [70 108 180];

% b) Linear interpolation at t = 5
HR_linear = interp1(time, HR, 5);
disp(HR_linear)

% c) Exact quadratic fit through all 3 points
p = polyfit(time, HR, 2);
HR_quad = polyval(p, 5);
disp(HR_quad)

% d) Compare
diffHR = HR_linear - HR_quad;
disp(diffHR)
% The two disagree because interp1's linear method only uses the two
% points bracketing t=5 (at t=4 and t=8) and draws a straight line
% between them, while polyfit's quadratic uses the shape formed by ALL
% three points (including the one at t=0) to determine its curvature,
% so it 'remembers' that heart rate was accelerating even as it
% evaluates a point between the later two samples.

% a) Define f and compute the true value at x = 1
f = @(x) 10*sqrt(x);
trueVal = f(1);

% b) Coarse sample
xCoarse = [0 4];
yCoarse = f(xCoarse);
yCoarse_est = interp1(xCoarse, yCoarse, 1);
errCoarse = abs(yCoarse_est - trueVal);

% c) Fine sample
xFine = [0 2 4];
yFine = f(xFine);
yFine_est = interp1(xFine, yFine, 1);
errFine = abs(yFine_est - trueVal);

% d) Compare
finerIsBetter = errFine < errCoarse;
disp(finerIsBetter)
% The finer sampling produces the smaller interpolation error because it
% adds a data point (at x=2) closer to the curved region near the query
% point, so the straight-line segment interp1 uses to estimate x=1 has
% less curvature to miss than the single, wide segment spanning the
% entire coarse interval.

% a) Define f and integration parameters
f = @(x) 4 - 0.5*x + 0.1*x.^2;
a = 0; b = 4; n = 8;
h = (b - a) / n;

% b) Build the composite trapezoidal sum with a for-loop
trapLoop = 0;
for i = 1:n
    xL = a + (i-1)*h;
    xR = a + i*h;
    trapLoop = trapLoop + h/2 * (f(xL) + f(xR));
end
disp(trapLoop)

% c) Compare against trapz
xv = a:h:b;
trapBuiltin = trapz(xv, f(xv));
disp(trapBuiltin)
disp(abs(trapLoop - trapBuiltin) < 1e-10)

% d) Exact value and error
trueValue = (4*b - 0.25*b^2 + (0.1/3)*b^3) - (4*a - 0.25*a^2 + (0.1/3)*a^3);
errorVal = abs(trapBuiltin - trueValue);
disp(errorVal)

% e) Accuracy check
isAccurate = errorVal < 0.01;
disp(isAccurate)
% With n = 8, the error (~0.0167) exceeds 0.01, so this step size is NOT
% fine enough for a clinical application requiring 2-decimal precision --
% a smaller h (more segments) would be needed.

% a) Define g and integration parameters
g = @(x) -0.5*x.^2 + 2*x + 1;
a2 = 0; b2 = 4; n2 = 4; h2 = 1;

% b) Build the composite midpoint sum with a for-loop
midpointLoop = 0;
for i = 1:n2
    xL = a2 + (i-1)*h2;
    xR = a2 + i*h2;
    xm = (xL + xR) / 2;
    midpointLoop = midpointLoop + h2 * g(xm);
end
disp(midpointLoop)

% c) Trapezoidal estimate
xv2 = a2:h2:b2;
trapzEstimate = trapz(xv2, g(xv2));
disp(trapzEstimate)

% d) Exact value and signed errors
trueValue2 = (-b2^3/6 + b2^2 + b2) - (-a2^3/6 + a2^2 + a2);
errorMid = midpointLoop - trueValue2;
errorTrap = trapzEstimate - trueValue2;
fprintf('errorMid = %.4f, errorTrap = %.4f\n', errorMid, errorTrap);

% e) The midpoint rule OVERestimates (errorMid > 0) and the trapezoidal
% rule UNDERestimates (errorTrap < 0) for this concave-down function.
% A straight chord between two points on a concave-down curve always
% dips below the curve, so trapezoidal (which uses that chord) misses
% area and comes in low; a midpoint rectangle instead pokes above the
% curve near each segment's edges, so it tends to overshoot instead.

